#include <iostream>
#include <string_view>

enum class GameStatus {
    Continue,
    Won,
    Lost
};

std::string_view getStatusName(GameStatus status) {
    switch (status) {
        case GameStatus::Continue: return "CONTINUE";
        case GameStatus::Won:      return "WON";
        case GameStatus::Lost:     return "LOST";
    }
    return "UNKNOWN";
}

int main() {
    int diceSum = 7;
    GameStatus status = GameStatus::Continue;

    if (diceSum == 7 || diceSum == 11) {
        status = GameStatus::Won;
    } else if (diceSum == 2 || diceSum == 3 || diceSum == 12) {
        status = GameStatus::Lost;
    }

    std::cout << "Sum: " << diceSum << " -> Status: " << getStatusName(status) << "\n";
    return 0;
}

#include <iostream>

void demonstrateStorage() {
    int autoVar = 10;         // Automatic storage duration
    static int staticVar = 10; // Static storage duration (initialized once)

    autoVar += 5;
    staticVar += 5;

    std::cout << "autoVar: " << autoVar << ", staticVar: " << staticVar << "\n";
}

int main() {
    demonstrateStorage();
    demonstrateStorage();
    demonstrateStorage();
    return 0;
}

#include <iostream>

int x = 1; // File scope (Global)

int main() {
    std::cout << "Global x: " << x << "\n";

    int x = 5; // Block scope in main (shadows global x)
    std::cout << "Outer block x: " << x << "\n";

    {
        int x = 7; // Inner block scope (shadows outer x)
        std::cout << "Inner block x: " << x << "\n";
        std::cout << "Access global x explicitly: " << ::x << "\n";
    }

    std::cout << "Outer block x restored: " << x << "\n";
    return 0;
}
